(window.__qhadithX=window.__qhadithX||{})[28]={"56":[{"c":"Sahih Bukhari","r":"Hadith 3884","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3884","x":"Narrated Al-Musaiyab:\n\nWhen Abu Talib was in his death bed, the Prophet (ﷺ) went to him while Abu Jahl was sitting beside him. The Prophet (ﷺ) said, \"O my uncle! Say: None has the right to be worshipped except Allah, an expression I will defend your case with, before Allah.\" Abu Jahl and `Abdullah bin Umaiya said, \"O Abu Talib! Will you leave the religion of `Abdul Muttalib?\" So they kept on saying this to him so that the last statement he said to them (before he died) was: \"I am on the religion of `Abdul Muttalib.\" Then the Prophet said, \" I will keep on asking for Allah's Forgiveness for you unless I am forbidden to do so.\" Then the following Verse was revealed:-- \"It is not fitting for the Prophet (ﷺ) and the believers to ask Allah's Forgiveness for the pagans, even if they were their near relatives, after it has become clear to them that they are the dwellers of the (Hell) Fire.\" (9.113) The other Verse was also revealed:-- \"(O Prophet!) Verily, you guide not whom you like, but Allah guides whom He will.......\" (28.56)","ar":"حَدَّثَنَا مَحْمُودٌ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنِ ابْنِ الْمُسَيَّبِ، عَنْ أَبِيهِ، أَنَّ أَبَا طَالِبٍ، لَمَّا حَضَرَتْهُ الْوَفَاةُ دَخَلَ عَلَيْهِ النَّبِيُّ صلى الله عليه وسلم وَعِنْدَهُ أَبُو جَهْلٍ فَقَالَ ‏\"‏ أَىْ عَمِّ، قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ‏.‏ كَلِمَةً أُحَاجُّ لَكَ بِهَا عِنْدَ اللَّهِ ‏\"‏‏.‏ فَقَالَ أَبُو جَهْلٍ وَعَبْدُ اللَّهِ بْنُ أَبِي أُمَيَّةَ يَا أَبَا طَالِبٍ، تَرْغَبُ عَنْ مِلَّةِ عَبْدِ الْمُطَّلِبِ فَلَمْ يَزَالاَ يُكَلِّمَانِهِ حَتَّى قَالَ آخِرَ شَىْءٍ كَلَّمَهُمْ بِهِ عَلَى مِلَّةِ عَبْدِ الْمُطَّلِبِ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ لأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنْهَ عَنْهُ ‏\"‏‏.‏ فَنَزَلَتْ ‏{‏مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ‏}‏ وَنَزَلَتْ ‏{‏إِنَّكَ لاَ تَهْدِي مَنْ أَحْبَبْتَ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4772","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4772","x":"Narrated Al-Musaiyab:\n\nWhen Abu Talib was on his death bed, Allah's Messenger (ﷺ) came to him and found with him, Abu Jahl and `Abdullah bin Abi Umaiya bin Al-Mughira. Allah's Messenger (ﷺ) said, \"O uncle! Say: None has the right to be worshipped except Allah, a sentence with which I will defend you before Allah.\" On that Abu Jahl and `Abdullah bin Abi Umaiya said to Abu Talib, \"Will you now leave the religion of `Abdul Muttalib?\" Allah's Messenger (ﷺ) kept on inviting him to say that sentence while the other two kept on repeating their sentence before him till Abu Talib said as the last thing he said to them, \"I am on the religion of `Abdul Muttalib,\" and refused to say: None has the right to be worshipped except Allah. On that Allah's Messenger (ﷺ) said, \"By Allah, I will keep on asking Allah's forgiveness for you unless I am forbidden (by Allah) to do so.\" So Allah revealed:-- 'It is not fitting for the Prophet (ﷺ) and those who believe that they should invoke (Allah) for forgiveness for pagans.' (9.113) And then Allah revealed especially about Abu Talib:--'Verily! You (O, Muhammad) guide not whom you like, but Allah guides whom He will.' (28.56)","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي سَعِيدُ بْنُ الْمُسَيَّبِ، عَنْ أَبِيهِ، قَالَ لَمَّا حَضَرَتْ أَبَا طَالِبٍ الْوَفَاةُ جَاءَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم فَوَجَدَ عِنْدَهِ أَبَا جَهْلٍ وَعَبْدَ اللَّهِ بْنَ أَبِي أُمَيَّةَ بْنِ الْمُغِيرَةِ، فَقَالَ ‏\"‏ أَىْ عَمِّ قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ، كَلِمَةً أُحَاجُّ لَكَ بِهَا عِنْدَ اللَّهِ ‏\"‏‏.‏ فَقَالَ أَبُو جَهْلٍ وَعَبْدُ اللَّهِ بْنُ أَبِي أُمَيَّةَ أَتَرْغَبُ عَنْ مِلَّةِ عَبْدِ الْمُطَّلِبِ فَلَمْ يَزَلْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَعْرِضُهَا عَلَيْهِ، وَيُعِيدَانِهِ بِتِلْكَ الْمَقَالَةِ حَتَّى قَالَ أَبُو طَالِبٍ آخِرَ مَا كَلَّمَهُمْ عَلَى مِلَّةِ عَبْدِ الْمُطَّلِبِ، وَأَبَى أَنْ يَقُولُ لاَ إِلَهَ إِلاَّ اللَّهُ‏.‏ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ وَاللَّهِ لأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنْهَ عَنْكَ ‏\"‏‏.‏ فَأَنْزَلَ اللَّهُ ‏{‏مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ‏}‏ وَأَنْزَلَ اللَّهُ فِي أَبِي طَالِبٍ، فَقَالَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم ‏{‏إِنَّكَ لاَ تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ‏}‏‏.‏ قَالَ ابْنُ عَبَّاسٍ ‏{‏أُولِي الْقُوَّةِ‏}‏ لاَ يَرْفَعُهَا الْعُصْبَةُ مِنَ الرِّجَالِ‏.‏ ‏{‏لَتَنُوءُ‏}‏ لَتُثْقِلُ‏.‏ ‏{‏فَارِغًا‏}‏ إِلاَّ مِنْ ذِكْرِ مُوسَى‏.‏ ‏{‏الْفَرِحِينَ‏}‏ الْمَرِحِينَ‏.‏ ‏{‏قُصِّيهِ‏}‏ اتَّبِعِي أَثَرَهُ، وَقَدْ يَكُونُ أَنْ يَقُصَّ الْكَلاَمَ ‏{‏نَحْنُ نَقُصُّ عَلَيْكَ‏}‏‏.‏ ‏{‏عَنْ جُنُبٍ‏}‏ عَنْ بُعْدٍ عَنْ جَنَابَةٍ وَاحِدٌ، وَعَنِ اجْتِنَابٍ أَيْضًا، يَبْطِشُ وَيَبْطُشُ‏.‏ ‏{‏يَأْتَمِرُونَ‏}‏ يَتَشَاوَرُونَ‏.‏ الْعُدْوَانُ وَالْعَدَاءُ وَالتَّعَدِّي وَاحِدٌ‏.‏ ‏{‏آنَسَ‏}‏ أَبْصَرَ‏.‏ الْجِذْوَةُ قِطْعَةٌ غَلِيظَةٌ مِنَ الْخَشَبِ، لَيْسَ فِيهَا لَهَبٌ، وَالشِّهَابُ فِيهِ لَهَبٌ‏.‏ وَالْحَيَّاتُ أَجْنَاسٌ الْجَانُّ وَالأَفَاعِي وَالأَسَاوِدُ‏.‏ ‏{‏رِدْءًا‏}‏ مُعِينًا‏.‏ قَالَ ابْنُ عَبَّاسٍ ‏{‏يُصَدِّقُنِي‏}‏ وَقَالَ غَيْرُهُ ‏{‏سَنَشُدُّ‏}‏ سَنُعِينُكَ كُلَّمَا عَزَّزْتَ شَيْئًا فَقَدْ جَعَلْتَ لَهُ عَضُدًا‏.‏ مَقْبُوحِينَ مُهْلَكِينَ‏.‏ ‏{‏وَصَّلْنَا‏}‏ بَيَّنَّاهُ وَأَتْمَمْنَاهُ‏.‏ ‏{‏يُجْبَى‏}‏ يُجْلَبُ ‏.‏‏{‏بَطِرَتْ‏}‏ أَشِرَتْ‏.‏ ‏{‏فِي أُمِّهَا رَسُولاً‏}‏ أُمُّ الْقُرَى مَكَّةُ وَمَا حَوْلَهَا‏.‏ ‏{‏تُكِنُّ‏}‏ تُخْفِي‏.‏ أَكْنَنْتُ الشَّىْءَ أَخْفَيْتُهُ، وَكَنَنْتُهُ أَخْفَيْتُهُ وَأَظْهَرْتُهُ‏.‏ ‏{‏وَيْكَأَنَّ اللَّهَ‏}‏ مِثْلُ أَلَمْ تَرَ أَنَّ اللَّهَ ‏{‏يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ وَيَقْدِرُ‏}‏ يُوَسِّعُ عَلَيْهِ وَيُضَيِّقُ عَلَيْهِ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 24a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-24a","x":"It is reported by Sa'id b. Musayyib who narrated it on the authority of his father (Musayyib b. Hazm) that when Abu Talib was about to die, the Messenger of Allah (ﷺ) came to him and found with him Abu Jahl ('Amr b. Hisham) and 'Abdullah b. Abi Umayya ibn al-Mughirah. The Messenger of Allah (ﷺ) said:\n\nMy uncle, you just make a profession that there is no god but Allah, and I will bear testimony before Allah (of your being a believer), Abu Jahl and 'Abdullah b. Abi Umayya addressing him said: Abu Talib, would you abandon the religion of 'Abdul-Muttalib? The Messenger of Allah (ﷺ) constantly requested him (to accept his offer), and (on the other hand) was repeated the same statement (of Abu Jahl and 'Abdullah b. Abi Umayya) till Abu Talib gave his final decision and be stuck to the religion of 'Abdul-Muttalib and refused to profess that there is no god but Allah. Upon this the Messenger of Allah remarked: By Allah, I will persistently beg pardon for you till I am forbidden to do so (by God), It was then that Allah, the Magnificent and the Glorious, revealed this verse: \" It is not meet for the Prophet and for those who believe that they should beg pardon for the polytheists, even though they were their kith and kin, after it had been made known to them that they were the denizens of Hell\" (ix. 113) And it was said to the Messenger of Allah (ﷺ): \" Verily thou canst not guide to the right path whom thou lovest. And it is Allah Who guideth whom He will, and He knoweth best who are the guided\" (xxviii, 56).","ar":"وَحَدَّثَنِي حَرْمَلَةُ بْنُ يَحْيَى التُّجِيبِيُّ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ وَهْبٍ، قَالَ أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي سَعِيدُ بْنُ الْمُسَيَّبِ، عَنْ أَبِيهِ، قَالَ لَمَّا حَضَرَتْ أَبَا طَالِبٍ الْوَفَاةُ جَاءَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم فَوَجَدَ عِنْدَهُ أَبَا جَهْلٍ وَعَبْدَ اللَّهِ بْنَ أَبِي أُمَيَّةَ بْنِ الْمُغِيرَةِ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَا عَمِّ قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ ‏.‏ كَلِمَةً أَشْهَدُ لَكَ بِهَا عِنْدَ اللَّهِ ‏\"‏ ‏.‏ فَقَالَ أَبُو جَهْلٍ وَعَبْدُ اللَّهِ بْنُ أَبِي أُمَيَّةَ يَا أَبَا طَالِبٍ أَتَرْغَبُ عَنْ مِلَّةِ عَبْدِ الْمُطَّلِبِ ‏.‏ فَلَمْ يَزَلْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَعْرِضُهَا عَلَيْهِ وَيُعِيدُ لَهُ تِلْكَ الْمَقَالَةَ حَتَّى قَالَ أَبُو طَالِبٍ آخِرَ مَا كَلَّمَهُمْ هُوَ عَلَى مِلَّةِ عَبْدِ الْمُطَّلِبِ ‏.‏ وَأَبَى أَنْ يَقُولَ لاَ إِلَهَ إِلاَّ اللَّهُ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَمَا وَاللَّهِ لأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنْهَ عَنْكَ ‏\"‏ ‏.‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ‏}‏ ‏.‏ وَأَنْزَلَ اللَّهُ تَعَالَى فِي أَبِي طَالِبٍ فَقَالَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم ‏{‏ إِنَّكَ لاَ تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ‏}‏‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 25a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-25a","x":"It is narrated on the authority of Abu Huraira that the Messenger of Allah said to his uncle at the time of his death:\n\nMake a profession of it that there is no god but Allah and I will bear testimony (of your being a Muslim) on the Day of judgment. But he (Abu Talib) refused to do so. Then Allah revealed this verse: \"Indeed, [O Muḥammad], you do not guide whom you like, but Allāh guides whom He wills. And He is most knowing of the [rightly] guided.\"(Quran 28:56).","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبَّادٍ، وَابْنُ أَبِي عُمَرَ، قَالاَ حَدَّثَنَا مَرْوَانُ، عَنْ يَزِيدَ، - وَهُوَ ابْنُ كَيْسَانَ - عَنْ أَبِي حَازِمٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِعَمِّهِ عِنْدَ الْمَوْتِ ‏\"‏ قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ لَكَ بِهَا يَوْمَ الْقِيَامَةِ ‏\"‏ ‏.‏ فَأَبَى فَأَنْزَلَ اللَّهُ ‏{‏ إِنَّكَ لاَ تَهْدِي مَنْ أَحْبَبْتَ‏}‏ الآيَةَ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 25b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-25b","x":"It is narrated on the authority of Abu Huraira that the Messenger of Allah said to his uncle (at the time of his death):\n\nMake a profession of it that there is no god but Allah and I will bear testimony (of your being a Muslim) on the Day of judgment. He (Abu Talib) said: Were it not the fear of the Quraysh blaming me (and) saying that it was the fear of (approaching death) that induced me to do so, I would have certainly delighted your eyes. It was then that Allah revealed: \"Indeed, [O Muḥammad], you do not guide whom you like, but Allāh guides whom He wills. And He is most knowing of the [rightly] guided.\"(Quran 28:56).","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ حَاتِمِ بْنِ مَيْمُونٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، حَدَّثَنَا يَزِيدُ بْنُ كَيْسَانَ، عَنْ أَبِي حَازِمٍ الأَشْجَعِيِّ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِعَمِّهِ ‏\"‏ قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ لَكَ بِهَا يَوْمَ الْقِيَامَةِ ‏\"‏ ‏.‏ قَالَ لَوْلاَ أَنْ تُعَيِّرَنِي قُرَيْشٌ يَقُولُونَ إِنَّمَا حَمَلَهُ عَلَى ذَلِكَ الْجَزَعُ لأَقْرَرْتُ بِهَا عَيْنَكَ فَأَنْزَلَ اللَّهُ ‏{‏ إِنَّكَ لاَ تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3188","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3188","x":"Narrated Abu Hurairah, may Allah be pleased with him:\n\n\"The Messenger of Allah (ﷺ) said to his uncle: 'Say La Ilaha Illallah and I may bear witness with that, on your behalf, on the Day of Judgement.' So he said: 'If it weren't that the Quraish would insult me (saying): \"He only said it out of fright\" then I would delight your eyes.' Then Allah the Mighty and Sublime revealed: Verily, you guide not whom you like, but Allah guides whom He wills (28:56).\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ يَزِيدَ بْنِ كَيْسَانَ، حَدَّثَنِي أَبُو حَازِمٍ الأَشْجَعِيُّ، هُوَ كُوفِيٌّ اسْمُهُ سَلْمَانُ مَوْلَى عَزَّةَ الأَشْجَعِيَّةِ عَنْ أَبِي هُرَيْرَةَ رضى الله عنه قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِعَمِّهِ ‏\"‏ قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدْ لَكَ بِهَا يَوْمَ الْقِيَامَةِ ‏\"‏ ‏.‏ فَقَالَ لَوْلاَ أَنْ تُعَيِّرَنِي بِهَا قُرَيْشٌ أَنَّمَا يَحْمِلُهُ عَلَيْهِ الْجَزَعُ لأَقْرَرْتُ بِهَا عَيْنَكَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏:‏ ‏(‏إنَّكَ لاَ تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ يَزِيدَ بْنِ كَيْسَانَ ‏.‏","v":[]}]};